// Ignorar mensajes administrativos publicados por el simulador
// (estado online/offline, heartbeat, etc.). Solo dejar pasar los
// mensajes de sensor reales.
if (msg.topic && msg.topic.startsWith('agricultura/sistema/')) {
    return null;
}
// Validar mínimamente que el payload sea un objeto con los campos esperados
if (typeof msg.payload !== 'object' || msg.payload === null) {
    node.warn('Payload no es un objeto JSON: ' + JSON.stringify(msg.payload).substring(0, 100));
    return null;
}
if (!msg.payload.variable || msg.payload.valor === undefined) {
    node.warn('Mensaje sin variable/valor: ' + msg.topic);
    return null;
}
return msg;

// =============================================================
// Transformación del mensaje del simulador a un punto InfluxDB v2
// =============================================================
// Formato real publicado por simulador_sensores.py (Fase 2):
//   topic   = agricultura/<cultivo>/<parcela>/<variable>
//   payload = {
//     timestamp_real, timestamp_simulado, parcela, cultivo,
//     ubicacion, variable, valor, unidad, sensor_id
//   }
//
// Cada mensaje contiene UNA variable de UN sensor de UNA parcela.
// Lo convertimos en UN punto InfluxDB con la variable como field
// dinámico, lo que permite consultas eficientes por (parcela, variable).
// =============================================================

const p = msg.payload;

// Construir dinámicamente el campo numérico con el nombre de la variable
// (temperatura_aire, humedad_relativa, precipitacion, etc.)
const fields = {};
fields[p.variable] = parseFloat(p.valor);

// Tags indexados (búsquedas rápidas por estos campos en InfluxDB)
const tags = {
    parcela:    p.parcela    || 'desconocida',
    cultivo:    p.cultivo    || 'desconocido',
    ubicacion:  p.ubicacion  || 'desconocida',
    variable:   p.variable   || 'desconocida',
    unidad:     p.unidad     || '',
    sensor_id:  p.sensor_id  || ''
};

// Timestamp: usar timestamp_real (UTC ISO-8601) si existe; fallback a Date.now()
let ts = Date.now();
if (p.timestamp_real) {
    const t = Date.parse(p.timestamp_real);
    if (!isNaN(t)) ts = t;
}

// Estructura que espera node-red-contrib-influxdb v2 (array)
msg.payload = [
    fields,
    tags
];
// El nodo InfluxDB Out usará el measurement definido en su configuración
// y aceptará msg.timestamp para fijar el tiempo del punto
msg.timestamp = ts;

return msg;
